                    "day": 1,
                    "month": 1,
                    "year": 2016
                }
            },
            "impressions": 8456,
            "nonchargeableClicks": 1,
            "pivot": "urn:li:sponsoredCampaign:10002907",
            "spend": {
                "amount": "142.00",
                "currencyCode": "USD"
